import { pill, heading } from './helpers.js';

export function settingsPage(
  {
    theme
  }
) {
  return `${heading('Settings')}<div class="settings-grid"><div class="stack"><section class="panel"><div class="panel-head"><span class="eyebrow">Appearance</span></div><div class="setting-row"><label for="theme">Theme</label><select id="theme"><option value="light" ${theme === 'light' ? 'selected' : ''}>Light</option><option value="dark" ${theme === 'dark' ? 'selected' : ''}>Dark</option><option value="system">System</option></select></div></section><section class="panel"><div class="panel-head"><span class="eyebrow">Providers</span></div><div class="setting-row"><div>Gemini<small>Tags · embeddings · relevance · generation</small></div><span class="provider-status">Not configured</span></div><div class="setting-row"><div>Tiger Data<small>Knowledge · vectors · events</small></div><span class="provider-status">Not configured</span></div><div class="setting-row"><div>Snowflake<small>Outcome classifier</small></div><span class="provider-status">Not configured</span></div></section><section class="panel"><div class="panel-head"><span class="eyebrow">Logging</span>${pill('Approved', 'green')}</div><div class="setting-row"><span>API & AI calls</span><strong>Metadata only</strong></div><div class="setting-row"><span>Retention</span><strong>30 days</strong></div><div class="setting-row"><span>Payloads & credentials</span><strong>Excluded</strong></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><span class="eyebrow">Codex integration</span></div><div class="panel-body"><dl class="settings-note"><dt>Editor</dt><dd>Separate refinement panel</dd><dt>Handoff</dt><dd>Copy prompt</dd><dt>Composer access</dt><dd>Not verified</dd><dt>Plugin transport</dt><dd>MCP · Planned</dd></dl></div></section><section class="panel"><div class="panel-head"><span class="eyebrow">Outcome classifier</span>${pill('Untrained')}</div><div class="panel-body facts"><div class="fact"><span>Labeled outcomes</span><span class="mono">0</span></div><div class="fact"><span>Model version</span><span>—</span></div></div></section></div></div>`;
}
